  console.log("compat-table/es2019/misc.optional-catch-binding.await.js: OK");
}

function testCode() {
  (async function () {
    try {
      await Promise.reject();
    }
    catch {
      asyncTestPassed();
    }
  })();
}

try {
  testCode();
  Promise.resolve().then(flushQueue);
} catch (e) {
  console.log("compat-table/es2019/misc.optional-catch-binding.await.js: exception: " + e);
